sys_variable_value.value:
(function execute(inputs, outputs) {

    gr = new GlideRecord('u_imp_tmpl_fm_expense_line');
    gr.deleteMultiple();

var loader = new GlideImportSetLoader();
	var importSetRec = loader.getImportSetGr(inputs.data_source_record);
	var ranload = loader.loadImportSetTable(importSetRec, inputs.data_source_record);
	importSetRec.state = "loaded";
	importSetRec.update();
	
	outputs.importset = importSetRec.getUniqueValue();

})(inputs, outputs);

